const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/workflows/bulk_replace_requests',
  headers: {'content-type': 'application/json'},
  body: {
    replacement_type: 'temporary',
    old_assignee_id: 'string',
    new_assignee_ids: ['string'],
    new_workflow_manager_id: 'string',
    start_date: '2019-08-24',
    end_date: '2019-08-24',
    modify_project_roles: true,
    reason: 'string',
    project_ids: ['string'],
    tools: [{type: 'string', sub_type: 'string'}]
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/workflows/bulk_replace_requests"),
    Content = new StringContent("{\"replacement_type\":\"temporary\",\"old_assignee_id\":\"string\",\"new_assignee_ids\":[\"string\"],\"new_workflow_manager_id\":\"string\",\"start_date\":\"2019-08-24\",\"end_date\":\"2019-08-24\",\"modify_project_roles\":true,\"reason\":\"string\",\"project_ids\":[\"string\"],\"tools\":[{\"type\":\"string\",\"sub_type\":\"string\"}]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

